import { RESOURCE_NOT_FOUND } from "../../errors/index.js";
import { createRemoteMCPToolSource, loadRemoteToolsFromSource, } from "../../tool/index.js";
import { clientAllowsStudioMcp } from "../runtime/client-profile.js";
import { bindToolExecutionIdentityContext, resolveToolExecutionIdentity, } from "../runtime/tool-execution-identity.js";
function studioMcpIdentitiesEqual(left, right) {
    return left.authToken === right.authToken && left.projectId === right.projectId;
}
function createStudioMcpIdentityContext(identity) {
    return {
        authToken: identity.authToken,
        ...(identity.projectId === null ? {} : { projectId: identity.projectId }),
    };
}
/** Builds studio MCP headers. */
export function buildStudioMcpHeaders(authToken, projectId, conversationId) {
    const headers = {
        Authorization: `Bearer ${authToken}`,
    };
    if (projectId) {
        headers["x-project-id"] = projectId;
    }
    if (conversationId) {
        headers["x-conversation-id"] = conversationId;
    }
    return headers;
}
async function loadStudioMcpState(input) {
    const boundIdentity = {
        authToken: input.authToken,
        projectId: input.projectId,
    };
    const source = input.createRemoteToolSource({
        id: input.sourceId,
        endpoint: input.url,
        headers: (context) => {
            const identity = resolveToolExecutionIdentity(context, boundIdentity.authToken, () => boundIdentity.projectId, "Studio execution context");
            return buildStudioMcpHeaders(identity.authToken, identity.projectId, input.conversationId);
        },
    });
    return {
        authToken: input.authToken,
        projectId: input.projectId,
        tools: await input.loadRemoteTools(source, {
            context: createStudioMcpIdentityContext(boundIdentity),
        }),
    };
}
/** Create live studio MCP tools. */
export async function createLiveStudioMcpTools(input) {
    const studioMcpUrl = input.studioMcpUrl;
    if (!studioMcpUrl || !clientAllowsStudioMcp(input.clientProfile)) {
        return {
            tools: {},
            close: async () => undefined,
        };
    }
    const sourceId = input.sourceId ?? "studio-mcp-live-tools";
    const createRemoteToolSource = input.createRemoteToolSource ?? createRemoteMCPToolSource;
    const loadRemoteTools = input.loadRemoteTools ?? loadRemoteToolsFromSource;
    let studioState = null;
    let pendingStates = [];
    let latestRequestedIdentity = null;
    let generation = 0;
    const getFallbackIdentity = () => resolveToolExecutionIdentity(undefined, input.authToken, input.getProjectId, "Studio execution context");
    const loadState = async (identity) => {
        const requestGeneration = generation;
        latestRequestedIdentity = identity;
        if (studioState && studioMcpIdentitiesEqual(studioState, identity)) {
            return studioState;
        }
        let pendingState = pendingStates.find((candidate) => candidate.generation === requestGeneration &&
            studioMcpIdentitiesEqual(candidate, identity));
        let createdPendingState = false;
        if (!pendingState) {
            pendingState = {
                ...identity,
                generation: requestGeneration,
                promise: loadStudioMcpState({
                    ...identity,
                    conversationId: input.conversationId,
                    url: studioMcpUrl,
                    sourceId,
                    createRemoteToolSource,
                    loadRemoteTools,
                }),
            };
            pendingStates.push(pendingState);
            createdPendingState = true;
        }
        try {
            const loadedState = await pendingState.promise;
            if (generation === requestGeneration &&
                latestRequestedIdentity &&
                studioMcpIdentitiesEqual(latestRequestedIdentity, loadedState)) {
                studioState = loadedState;
            }
            return loadedState;
        }
        finally {
            if (createdPendingState) {
                pendingStates = pendingStates.filter((candidate) => candidate !== pendingState);
            }
        }
    };
    const initialState = await loadState(getFallbackIdentity());
    const wrappedTools = {};
    for (const [toolName, toolDefinition] of Object.entries(initialState.tools)) {
        if (typeof toolDefinition.execute !== "function") {
            wrappedTools[toolName] = toolDefinition;
            continue;
        }
        wrappedTools[toolName] = {
            ...toolDefinition,
            execute: async (toolInput, execOptions) => {
                const identity = resolveToolExecutionIdentity(execOptions, input.authToken, input.getProjectId, "Studio execution context");
                const liveState = await loadState(identity);
                const liveTool = liveState.tools[toolName];
                if (!liveTool || typeof liveTool.execute !== "function") {
                    throw RESOURCE_NOT_FOUND.create({
                        detail: `Studio MCP tool unavailable for current project: ${toolName}`,
                    });
                }
                return liveTool.execute(toolInput, bindToolExecutionIdentityContext(execOptions, identity, "Studio execution context"));
            },
        };
    }
    return {
        tools: wrappedTools,
        close: async () => {
            generation += 1;
            latestRequestedIdentity = null;
            studioState = null;
            pendingStates = [];
        },
    };
}
